"""
Contract: perceive(observation_history) -> str must never raise.
Outputs a compact summary of non-background cells and the agent's position,
including when the agent is off-grid (using history to recover last known location).
This enables reliable action recovery from consecutive states.
"""

import json
from collections import Counter


def _parse_grid(obs: str):
    """Extract the 2D colour grid as list[list[str]] (rows of colour-name strings).

    Anchor on the generic '[[' / ']]' so it works regardless of header text.
    Returns None on failure (caller degrades gracefully)."""
    if not obs:
        return None
    start = obs.find("[[")
    end = obs.rfind("]]")
    if start == -1 or end == -1 or end < start:
        return None
    try:
        grid = json.loads(obs[start: end + 2])
    except Exception:
        return None
    if not grid or not isinstance(grid, list) or not isinstance(grid[0], list):
        return None
    return grid


def _determine_background(grid):
    """Return the most frequent colour in the grid (the background)."""
    colours = [cell for row in grid for cell in row]
    if not colours:
        return "black"  # fallback
    counter = Counter(colours)
    return counter.most_common(1)[0][0]


def _find_agent(grid):
    """Return (row, col) of the orange cell, or None if not present."""
    for r, row in enumerate(grid):
        for c, col in enumerate(row):
            if col == "orange":
                return (r, c)
    return None


def perceive(observation_history: list[str]) -> str:
    # Always take the current observation
    obs = observation_history[-1] if observation_history else ""
    grid = _parse_grid(obs)
    if grid is None:
        return "parse error, could not extract grid"

    try:
        background = _determine_background(grid)
    except Exception:
        background = "black"

    agent_pos = None  # (r, c) if on grid
    # Look for orange in current grid
    agent_pos = _find_agent(grid)

    other_cells = []
    try:
        for r, row in enumerate(grid):
            for c, colour in enumerate(row):
                if colour == background:
                    continue
                if colour == "orange":
                    continue  # already handled
                other_cells.append((r, c, colour))
    except Exception:
        return "grid error"

    # If agent is off-grid, recover its last known position from history
    if agent_pos is None:
        # Search backwards through history for the most recent orange
        for i in range(len(observation_history) - 2, -1, -1):
            prev_obs = observation_history[i]
            prev_grid = _parse_grid(prev_obs)
            if prev_grid is not None:
                prev_agent = _find_agent(prev_grid)
                if prev_agent is not None:
                    agent_pos = ("off", prev_agent[0], prev_agent[1])
                    break
        # If still not found, leave as None (unknown)
        # In practice, game always starts with agent visible, so this is safe.

    # Sort other cells deterministically
    other_cells.sort(key=lambda x: (x[0], x[1]))

    # Build output
    parts = []
    if agent_pos is not None:
        if isinstance(agent_pos, tuple) and agent_pos[0] != "off":
            r, c = agent_pos
            parts.append(f"agent row={r} col={c}")
        else:
            # agent off : stored as ("off", r, c)
            parts.append(f"agent off last row={agent_pos[1]} col={agent_pos[2]}")
    else:
        # Truly unknown - this shouldn't happen in practice, but be safe
        parts.append("agent unknown")

    if other_cells:
        cell_strs = [f"({r},{c},{col})" for r, c, col in other_cells]
        combined = "; ".join(cell_strs)
        if len(combined) > 1900:  # leave room for rest
            max_shown = 50
            truncated = cell_strs[:max_shown]
            truncated_str = "; ".join(truncated)
            parts.append(f"others ({len(cell_strs)} total, first {max_shown}): {truncated_str}")
        else:
            parts.append(f"others: {combined}")

    # Ensure result is never empty
    result = " | ".join(parts)
    if not result:
        result = "grid error"
    elif len(result) > 2000:
        result = result[:1997] + "..."
    return result

"""
Contract: perceive(observation_history) -> str must never raise.
Outputs a compact but discriminative summary of all non‑background cells,
the agent’s presence/position, and the delta from the previous state.
The output is designed so that consecutive states uniquely determine the action.

Output format (|‑separated), total <2000 chars:
  bg=<colour>|a(r,c) or a(none)|ap=T/F|er=<expected_row> (if applicable)|others=<list>|delta=<list>
where <list> uses (r,c,colour) and delta uses +/‑/~ prefixes.
"""

import json
from collections import Counter

def _parse_grid(obs: str):
    """Extract the 2D colour grid as list[list[str]] (rows of colour-name strings).
    Returns None on any parse failure."""
    if not obs:
        return None
    start = obs.find("[[")
    end = obs.rfind("]]")
    if start == -1 or end == -1 or end < start:
        return None
    try:
        grid = json.loads(obs[start: end + 2])
    except Exception:
        return None
    if not grid or not isinstance(grid, list) or not isinstance(grid[0], list):
        return None
    return grid

def _determine_background(grid):
    """Return the most frequent colour in the grid (the background)."""
    colours = [cell for row in grid for cell in row]
    if not colours:
        return "black"
    counter = Counter(colours)
    return counter.most_common(1)[0][0]

def _extract_cells(grid, background):
    """Return a dict {(r,c): colour, ...} for all non‑background cells."""
    cells = {}
    try:
        for r, row in enumerate(grid):
            for c, colour in enumerate(row):
                if colour != background:
                    cells[(r, c)] = colour
    except Exception:
        pass
    return cells

def _format_cell_list(cells_dict):
    """Format a dict of non‑agent cells into a compact string.
    Returns 'none' if empty."""
    if not cells_dict:
        return "none"
    items = sorted(cells_dict.items(), key=lambda x: (x[0][0], x[0][1]))
    parts = [f"({r},{c},{col})" for (r, c), col in items]
    return ";".join(parts)

def _format_delta(added, removed, changed):
    """Format delta changes into a compact string.
    added : dict (r,c)->colour
    removed : dict (r,c)->colour
    changed : dict (r,c)->(old,new)
    Returns string like '+(...);~(...);-(...)' or 'none'."""
    parts = []
    for (r, c), col in sorted(removed.items(), key=lambda x: (x[0][0], x[0][1])):
        parts.append(f"-({r},{c},{col})")
    for (r, c), (old, new) in sorted(changed.items(), key=lambda x: (x[0][0], x[0][1])):
        parts.append(f"~({r},{c},{old}->{new})")
    for (r, c), col in sorted(added.items(), key=lambda x: (x[0][0], x[0][1])):
        parts.append(f"+({r},{c},{col})")
    return ";".join(parts) if parts else "none"

def perceive(observation_history: list[str]) -> str:
    # ---------- parse current observation ----------
    obs_cur = observation_history[-1] if observation_history else ""
    grid_cur = _parse_grid(obs_cur)
    if grid_cur is None:
        return "bg=unknown|a(none)|ap=F|others=none|delta=none"

    try:
        bg = _determine_background(grid_cur)
    except Exception:
        bg = "black"

    cells_cur = _extract_cells(grid_cur, bg)

    # Separate agent (orange)
    agent_cur = None
    others_cur = {}
    for (r, c), col in cells_cur.items():
        if col == "orange":
            agent_cur = (r, c)
        else:
            others_cur[(r, c)] = col

    # ---------- build current state string ----------
    agent_str = f"a({agent_cur[0]},{agent_cur[1]})" if agent_cur is not None else "a(none)"
    ap_str = "ap=T" if agent_cur is not None else "ap=F"
    others_str = _format_cell_list(others_cur)

    # Expected row (if previous state had an agent)
    er_str = ""
    if len(observation_history) >= 2:
        obs_prev = observation_history[-2]
        grid_prev = _parse_grid(obs_prev)
        if grid_prev is not None:
            try:
                bg_prev = _determine_background(grid_prev)
            except Exception:
                bg_prev = bg
            cells_prev = _extract_cells(grid_prev, bg_prev)
            # find agent in previous
            prev_agent = None
            for (r, c), col in cells_prev.items():
                if col == "orange":
                    prev_agent = (r, c)
                    break
            if prev_agent is not None:
                if prev_agent[0] == 15:
                    expected_row = 1
                else:
                    expected_row = prev_agent[0] + 1
                er_str = f"er={expected_row}"

    cur_part = f"bg={bg}|{agent_str}|{ap_str}"
    if er_str:
        cur_part += f"|{er_str}"
    cur_part += f"|others={others_str}"

    # ---------- compute delta ----------
    delta_str = "delta=none"
    if len(observation_history) >= 2:
        obs_prev = observation_history[-2]
        grid_prev = _parse_grid(obs_prev)
        if grid_prev is not None:
            try:
                bg_prev = _determine_background(grid_prev)
            except Exception:
                bg_prev = bg
            cells_prev = _extract_cells(grid_prev, bg_prev)

            added = {}
            removed = {}
            changed = {}
            keys_cur = set(cells_cur.keys())
            keys_prev = set(cells_prev.keys())
            for k in keys_cur - keys_prev:
                added[k] = cells_cur[k]
            for k in keys_prev - keys_cur:
                removed[k] = cells_prev[k]
            for k in keys_cur & keys_prev:
                if cells_cur[k] != cells_prev[k]:
                    changed[k] = (cells_prev[k], cells_cur[k])
            d = _format_delta(added, removed, changed)
            if d != "none":
                delta_str = f"delta={d}"

    result = f"{cur_part}|{delta_str}"

    # ---------- length safety ----------
    if len(result) > 2000:
        # Truncate the "others" part first
        # Rebuild without others, then add a hash or truncated version
        base = f"bg={bg}|{agent_str}|{ap_str}"
        if er_str:
            base += f"|{er_str}"
        base += "|others="
        # Keep delta intact
        tail = f"|{delta_str}"
        max_others = 2000 - len(base) - len(tail) - 5  # margin
        if max_others > 0:
            truncated_others = others_str[:max_others] + "..."
            result = base + truncated_others + tail
        else:
            # Drop others entirely
            result = f"{base}TRUNC|{tail}"
    if not result:
        result = "bg=unknown|a(none)|ap=F|others=none|delta=none"
    return result

"""
Perception module for grid environments.
Outputs a compact but fully discriminative summary of all non‑background cells,
the agent's presence/position, the delta from the previous observation, and
a behavioural type label for each colour (where known) to assist inverse dynamics.
The output is designed so that consecutive states (with delta) uniquely determine
the action taken, even when evidence lies several steps away.

Output format (|‑separated), total <2000 chars:
  bg=<colour>|a(r,c) or a(none)|ap=T/F|others=<list>|delta=<list>
where <list> uses (r,c,colour:type) and delta uses +/‑/~ prefixes.
Type abbreviations:
  S = static (blue)
  F = fall (red) – moves down each step
  M = move (gray) – moves on directional actions
  A = agent (orange) – moves one row down each step, reacts to actions
  U = unknown (other colours)
If a colour is not recognised, the type is omitted (just colour name).
"""

import json
from collections import Counter

# Known colour-to-behaviour mapping (can be extended)
COLOUR_BEHAVIOUR = {
    "blue": "S",
    "red": "F",
    "gray": "M",
    "grey": "M",
    "orange": "A",
}

def _parse_grid(obs: str):
    """Extract the 2D colour grid as list[list[str]] (rows of colour-name strings).
    Returns None on any parse failure."""
    if not obs:
        return None
    start = obs.find("[[")
    end = obs.rfind("]]")
    if start == -1 or end == -1 or end < start:
        return None
    try:
        grid = json.loads(obs[start: end + 2])
    except Exception:
        return None
    if not grid or not isinstance(grid, list) or not isinstance(grid[0], list):
        return None
    return grid

def _determine_background(grid):
    """Return the most frequent colour in the grid (the background)."""
    colours = [cell for row in grid for cell in row]
    if not colours:
        return "black"
    counter = Counter(colours)
    return counter.most_common(1)[0][0]

def _extract_cells(grid, background):
    """Return a dict {(r,c): colour, ...} for all non‑background cells."""
    cells = {}
    try:
        for r, row in enumerate(grid):
            for c, colour in enumerate(row):
                if colour != background:
                    cells[(r, c)] = colour
    except Exception:
        pass
    return cells

def _cell_tag(colour):
    """Return a compact tag for a colour (e.g. 'blue:S', 'orange:A')."""
    tag = COLOUR_BEHAVIOUR.get(colour.lower())
    return f"{colour}:{tag}" if tag else colour

def _format_cell_list(cells_dict):
    """Format a dict of cells into a compact string with behavioural tags.
    Returns 'none' if empty."""
    if not cells_dict:
        return "none"
    items = sorted(cells_dict.items(), key=lambda x: (x[0][0], x[0][1]))
    parts = [f"({r},{c},{_cell_tag(col)})" for (r, c), col in items]
    return ";".join(parts)

def _format_delta(added, removed, changed):
    """Format delta changes into a compact string.
    added : dict (r,c)->colour
    removed : dict (r,c)->colour
    changed : dict (r,c)->(old,new)
    Returns string like '+(...);~(...);-(...)' or 'none'."""
    parts = []
    for (r, c), col in sorted(removed.items(), key=lambda x: (x[0][0], x[0][1])):
        parts.append(f"-({r},{c},{_cell_tag(col)})")
    for (r, c), (old, new) in sorted(changed.items(), key=lambda x: (x[0][0], x[0][1])):
        parts.append(f"~({r},{c},{_cell_tag(old)}->{_cell_tag(new)})")
    for (r, c), col in sorted(added.items(), key=lambda x: (x[0][0], x[0][1])):
        parts.append(f"+({r},{c},{_cell_tag(col)})")
    return ";".join(parts) if parts else "none"

def perceive(observation_history: list[str]) -> str:
    # --- parse current observation ---
    obs_cur = observation_history[-1] if observation_history else ""
    grid_cur = _parse_grid(obs_cur)
    if grid_cur is None:
        return "bg=unknown|a(none)|ap=F|others=none|delta=none"

    try:
        bg = _determine_background(grid_cur)
    except Exception:
        bg = "black"

    cells_cur = _extract_cells(grid_cur, bg)

    # separate agent (orange) from others
    agent_cur = None
    others_cur = {}
    for (r, c), col in cells_cur.items():
        if col.lower() == "orange":
            agent_cur = (r, c)
        else:
            others_cur[(r, c)] = col

    agent_str = f"a({agent_cur[0]},{agent_cur[1]})" if agent_cur is not None else "a(none)"
    ap_str = "ap=T" if agent_cur is not None else "ap=F"
    others_str = _format_cell_list(others_cur)

    # --- compute delta from previous observation (if available) ---
    delta_str = "delta=none"
    if len(observation_history) >= 2:
        obs_prev = observation_history[-2]
        grid_prev = _parse_grid(obs_prev)
        if grid_prev is not None:
            try:
                bg_prev = _determine_background(grid_prev)
            except Exception:
                bg_prev = bg
            cells_prev = _extract_cells(grid_prev, bg_prev)

            # delta over all cells (including agent)
            added = {}
            removed = {}
            changed = {}
            keys_cur = set(cells_cur.keys())
            keys_prev = set(cells_prev.keys())
            for k in keys_cur - keys_prev:
                added[k] = cells_cur[k]
            for k in keys_prev - keys_cur:
                removed[k] = cells_prev[k]
            for k in keys_cur & keys_prev:
                if cells_cur[k] != cells_prev[k]:
                    changed[k] = (cells_prev[k], cells_cur[k])
            d = _format_delta(added, removed, changed)
            if d != "none":
                delta_str = f"delta={d}"

    result = f"bg={bg}|{agent_str}|{ap_str}|others={others_str}|{delta_str}"

    # --- length safety (truncate others if needed) ---
    if len(result) > 2000:
        # keep everything except others, truncate others
        base = f"bg={bg}|{agent_str}|{ap_str}|others="
        tail = f"|{delta_str}"
        max_others = 2000 - len(base) - len(tail) - 5  # margin for "..."
        if max_others > 0:
            truncated_others = others_str[:max_others] + "..."
            result = base + truncated_others + tail
        else:
            # fallback: drop others completely
            result = base + "TRUNC" + tail

    if not result:
        result = "bg=unknown|a(none)|ap=F|others=none|delta=none"
    return result
